const radiusKm = 3; // raio em km

const body = $input.first().json;
const payload = Array.isArray(body) ? body[0] : body;

if (!payload || !payload.results || !payload.results[0]) {
  throw new Error('Resposta do Maps não tem results[0]');
}

const loc = payload.results[0].geometry.location;
const lat0 = loc.lat;
const lng0 = loc.lng;

// --- bbox numérico ---
const radiusMeters = radiusKm * 1000;
const degPerMeterLat = 1 / 111320;
const latRad = lat0 * Math.PI / 180;

const deltaLat = radiusMeters * degPerMeterLat;
const degPerMeterLng = 1 / (111320 * Math.cos(latRad));
const deltaLng = radiusMeters * degPerMeterLng;

const latMinNum = lat0 - deltaLat;
const latMaxNum = lat0 + deltaLat;
const lngMinNum = lng0 - deltaLng;
const lngMaxNum = lng0 + deltaLng;

// --- função que garante ORDEM DE STRING correta p/ Vista ---
function rangeAsStrings(minNum, maxNum) {
  let a = minNum.toString();
  let b = maxNum.toString();
  if (a > b) {
    [a, b] = [b, a]; // garante que a < b como string
  }
  return [a, b];
}

const [latMinStr, latMaxStr] = rangeAsStrings(latMinNum, latMaxNum);
const [lngMinStr, lngMaxStr] = rangeAsStrings(lngMinNum, lngMaxNum);

return [
  {
    json: {
      Latitude: [latMinStr, latMaxStr],
      Longitude: [lngMinStr, lngMaxStr],
    },
  },
];
